veltInitializeUserContent:
"use client";

import { useAppUser } from "@/app/userAuth/useAppUser";
import type { VeltAuthProvider } from "@veltdev/types";
import { useMemo, useEffect } from "react";
import { saveCurrentUserToDB } from "./VeltDataProviders";

// [Velt] Call your backend API to generate a JWT token for the user
async function getVeltJwtFromBackend(user: {
  userId: string;
  organizationId: string;
  email?: string;
}) {
  const resp = await fetch("/api/velt/token", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      userId: user.userId,
      organizationId: user.organizationId,
      email: user.email,
      isAdmin: true, // Use this to assign admin privileges to the user
    }),
    cache: "no-store",
  });
  if (!resp.ok) {
    const err = await resp.json().catch(() => ({}));
    throw new Error(`Token API failed: ${err?.error || resp.statusText}`);
  }
  const { token } = await resp.json();
  console.log('Info: Velt JWT token:', token);
  if (!token) throw new Error("No token in response");
  return token as string;
}

export function useVeltAuthProvider() {
  // [Velt] Get your app's current authenticated user to authenticate with Velt.
  const { user } = useAppUser();

  // [Velt Self-Host] Save user to database for self-hosted user PII
  useEffect(() => {
    if (user) {
      saveCurrentUserToDB({ ...user });
    }
  }, [user]);

  // [Velt] Create auth provider object to pass to VeltProvider
  const authProvider: VeltAuthProvider | undefined = useMemo(() => {
    if (!user) return undefined;
    return {
      user,
      retryConfig: { retryCount: 3, retryDelay: 1000 },
      generateToken: async () => {
        return await getVeltJwtFromBackend({
          userId: user.userId as string,
          organizationId: user.organizationId as string,
          email: user.email,
        });
      },
    };
  }, [user]);

  return { authProvider };
}

veltInitializeDocumentContent:
"use client";
import { useEffect } from 'react';
import { useSetDocuments, useCurrentUser } from '@veltdev/react';
import { useJobs, JOBS_LIST_DOCUMENT_ID, JOBS_LIST_DOCUMENT_NAME } from '@/app/document/JobsContext';

export default function VeltInitializeDocument() {
  // [Velt] Get document setter hook
  const { setDocuments } = useSetDocuments();

  // [Velt] Wait for Velt user to be authenticated before setting document
  const veltUser = useCurrentUser();

  // [Velt] Get the selected job and page state
  const { selectedJob, isOnJobsListPage } = useJobs();

  // [Velt] Set document in Velt based on current page
  useEffect(() => {
    if (!veltUser) return;
    if (isOnJobsListPage) {
      setDocuments([
        { id: JOBS_LIST_DOCUMENT_ID, metadata: { documentName: JOBS_LIST_DOCUMENT_NAME } },
      ]);
    } else if (selectedJob && selectedJob.id && selectedJob.jobName) {
      setDocuments([
        { id: selectedJob.id, metadata: { documentName: selectedJob.jobName } },
      ]);
    }
  }, [veltUser, setDocuments, isOnJobsListPage, selectedJob]);

  return null;
}

veltCollaborationContent:
"use client";
import { useAppUser } from "@/app/userAuth/AppUserContext";
import { useVeltClient, VeltComments, VeltCommentsSidebar } from "@veltdev/react";
import { useEffect } from "react";
import VeltInitializeDocument from "./VeltInitializeDocument";
import { VeltCustomization } from "./ui-customization/VeltCustomization";
import { useSelectedJob } from "@/app/document/JobsContext";

export function VeltCollaboration() {
    const { isUserLoggedIn } = useAppUser();
    // [Velt] Get Velt client instance
    const { client } = useVeltClient();

    const selectedJob = useSelectedJob();

    // [Velt] Sign out user when user logs out, getting user login state from host app
    useEffect(() => {
        if (isUserLoggedIn === false && client) {
            client.signOutUser();
        }
    }, [isUserLoggedIn, client]);

    const groupConfig = {
        enable: false
    };

    return (
        <>
            <VeltInitializeDocument />
            <VeltComments
                popoverTriangleComponent={false}
                popoverMode={true}
                shadowDom={false}
                textMode={false}
                commentPinHighlighter={false}
                dialogOnHover={false}
                groupMatchedComments={true}
                autoCompleteScrollConfig={{
                    itemSize: 28,
                }}
            // readOnly={true} // Uncomment this to make the comments read-only for certain users
            />
            <VeltCommentsSidebar
                context={{ jobId: selectedJob?.id, jobName: selectedJob?.jobName, jobStatus: selectedJob?.status, commentType: 'jobLevel' }}
                shadowDom={false}
                groupConfig={groupConfig}
                pageMode={true}
                sortOrder="asc"
                sortBy="createdAt"
                focusedThreadMode={true}
                openAnnotationInFocusMode={true}
                defaultMinimalFilter="reset"
                forceClose={true}
            // readOnly={true}
            />

            <VeltCustomization />
        </>
    );
}

